-- Dual public form templates:
-- 1) profession_health_plan → team-scoped (Kathrein Antunes), exclusive WhatsApp CTA
-- 2) basic_form → global copy of the same draft content for every team
--
-- Listing API: teamId IS NULL OR teamId = currentTeam.

-- Keep Kathrein scope on profession_health_plan (idempotent).
UPDATE public.corretor_studio_public_form_templates AS t
SET
  "teamId" = k.id,
  "sortOrder" = 25,
  "updatedAt" = now()
FROM (
  SELECT id
  FROM public.corretor_studio_teams
  WHERE id = '28f7b9e8-9516-4a08-864c-9ff3e085ba87'::uuid
) AS k
WHERE t."slug" = 'profession_health_plan'
  AND (
    t."teamId" IS NULL
    OR t."teamId" IS DISTINCT FROM k.id
    OR t."sortOrder" IS DISTINCT FROM 25
  );

